import {money} from './store.js';
export function moscowDay(date){const d=new Date(date);if(!Number.isFinite(d.getTime()))return '';const p=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d);return ['year','month','day'].map(k=>p.find(x=>x.type===k).value).join('-');}
const empty=()=>({revenue:0,commission:0,due:0,paid:0,quantity:0,orders:0});
export function analytics(state,month=moscowDay(new Date()).slice(0,7)){
 if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(month))throw Error('Invalid month');
 const [year,m]=month.split('-').map(Number),days=Array.from({length:new Date(Date.UTC(year,m,0)).getUTCDate()},(_,i)=>({key:month+'-'+String(i+1).padStart(2,'0'),label:String(i+1),...empty()}));
 const months=new Map(),suppliers=new Map(),products=new Map(),categories=new Map(),sales=[],payments=[];
 const bucket=key=>{if(!months.has(key))months.set(key,{key,label:key,...empty()});return months.get(key);};
 const partner=(id,name)=>{if(!suppliers.has(id))suppliers.set(id,{id,name:name||state.suppliers.find(s=>s.id===id)?.name||id||'Не указан',...empty()});return suppliers.get(id);};
 const total=empty();let openingDue=0,openingPaid=0;
 for(const o of state.orders){if(o.status!=='sold')continue;const day=moscowDay(o.confirmedAt||o.date);if(!day)continue;const key=day.slice(0,7),row=bucket(key),daily=days.find(d=>d.key===day);row.orders++;if(daily){daily.orders++;total.orders++;}
 for(const item of o.items){const revenue=item.price*item.quantity,commission=item.commission??(item.due!=null?revenue-item.due:0),due=item.due??revenue-commission;
 for(const r of [row,...(daily?[daily,total]:[])]){r.revenue+=revenue;r.commission+=commission;r.due+=due;r.quantity+=item.quantity;}
 if(key<month)openingDue+=due;if(!daily)continue;
 const p=state.products.find(p=>p.id===item.id),supplier=partner(item.supplier,item.supplierName),category=item.category||p?.category||'Категория не сохранена';
 for(const [map,id,name] of [[products,item.id,item.name],[categories,category,category]]){if(!map.has(id))map.set(id,{id,name,...empty()});const r=map.get(id);r.revenue+=revenue;r.commission+=commission;r.quantity+=item.quantity;}
 supplier.revenue+=revenue;supplier.commission+=commission;supplier.due+=due;supplier.quantity+=item.quantity;
 sales.push({order:o.id,date:day,buyer:o.buyer?.name||o.userId||'Не сохранён',name:item.name,supplier:supplier.name,quantity:item.quantity,revenue,commission});
 }}
 for(const p of state.payouts){const day=moscowDay(p.date);if(!day)continue;const key=day.slice(0,7);bucket(key).paid+=p.amount;if(key<month)openingPaid+=p.amount;if(key!==month)continue;
 total.paid+=p.amount;days.find(d=>d.key===day).paid+=p.amount;const supplier=partner(p.supplier,p.supplierName);supplier.paid+=p.amount;payments.push({...p,day,supplierName:supplier.name,actorName:p.actorName||'Не сохранён в старой записи'});}
 const current=moscowDay(new Date()).slice(0,7);bucket(current);bucket(month);
 const start=[...months.keys()].sort()[0],end=[...months.keys()].sort().at(-1);let cursor=start;while(cursor<=end){bucket(cursor);const [y,n]=cursor.split('-').map(Number);cursor=new Date(Date.UTC(y,n,1)).toISOString().slice(0,7);}
 const sort=map=>[...map.values()].sort((a,b)=>b.revenue-a.revenue||b.quantity-a.quantity);
 return {month,days,months:[...months.values()].sort((a,b)=>a.key.localeCompare(b.key)),total,openingBalance:openingDue-openingPaid,closingBalance:openingDue-openingPaid+total.due-total.paid,suppliers:sort(suppliers),products:sort(products),categories:sort(categories),sales,payments};
}
function chart(rows,metric,esc){const max=Math.max(1,...rows.map(r=>r[metric]));return `<div class="analytics-chart" role="img" aria-label="${metric==='quantity'?'Продано штук':'Суммы в рублях'} по периодам">${rows.map(r=>`<div class="analytics-column"><div class="analytics-bar" style="height:${r[metric]/max*160}px" title="${esc(r.label)}: ${metric==='quantity'?r[metric]+' шт.':money(r[metric])}"></div><small>${esc(r.label)}</small></div>`).join('')}</div>`;}
export function analyticsView(state,selection,esc){const a=analytics(state,selection.month),metric=['quantity','revenue','commission','paid'].includes(selection.metric)?selection.metric:'quantity',year=selection.year||a.month.slice(0,4),years=[...new Set(a.months.map(r=>r.key.slice(0,4)))],months=Array.from({length:12},(_,i)=>{const key=year+'-'+String(i+1).padStart(2,'0');return a.months.find(r=>r.key===key)||{key,label:key,...empty()};});const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${heads.length}">Нет записей за этот месяц</td></tr>`}</tbody></table></div>`;
 return `<h1>Аналитика</h1><div class="analytics-controls"><label>Месяц<select id="analytics-month">${[...a.months].reverse().map(r=>`<option value="${r.key}" ${r.key===a.month?'selected':''}>${r.key}</option>`).join('')}</select></label><label>Показатель графика<select id="analytics-metric">${[['quantity','Продано, шт.'],['revenue','Продажи, ₽'],['commission','Комиссия, ₽'],['paid','Выплаты, ₽']].map(([v,t])=>`<option value="${v}" ${v===metric?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="stats analytics-stats">${[['Продажи',money(a.total.revenue)],['Комиссия магазина',money(a.total.commission)],['Выплачено поставщикам',money(a.total.paid)],['Продано вещей',a.total.quantity],['Подтверждено заказов',a.total.orders],['Долг на конец месяца',money(a.closingBalance)]].map(([label,value])=>`<div class="stat"><span>${label}</span><strong>${value}</strong></div>`).join('')}</div><p class="small muted">Комиссия — доход магазина до расходов и налогов. Продажи учитываются по подтверждению, выплаты — по дате записи; время московское. Долг на начало месяца: ${money(a.openingBalance)}.</p><h2>По дням · ${a.month}</h2>${chart(a.days,metric,esc)}<details><summary>Точные значения по дням</summary>${table(['День','Шт.','Продажи','Комиссия','Выплаты'],a.days.map(r=>[r.label,r.quantity,money(r.revenue),money(r.commission),money(r.paid)]))}</details><div class="analytics-controls"><h2>По месяцам</h2><label>Год<select id="analytics-year">${years.map(y=>`<option ${y===year?'selected':''}>${y}</option>`).join('')}</select></label></div>${chart(months,metric,esc)}${table(['Месяц','Шт.','Продажи','Комиссия','Выплачено'],months.map(r=>[`<button type="button" class="text-link" data-action="analytics-month" data-month="${r.key}">${r.key}</button>`,r.quantity,money(r.revenue),money(r.commission),money(r.paid)]))}<h2>Поставщики · ${a.month}</h2>${table(['Поставщик','Шт.','Продажи','Комиссия','Начислено','Выплачено'],a.suppliers.map(r=>[esc(r.name),r.quantity,money(r.revenue),money(r.commission),money(r.due),money(r.paid)]))}<h2>Товары по выручке</h2>${table(['Товар','Шт.','Продажи','Комиссия'],a.products.map(r=>[esc(r.name),r.quantity,money(r.revenue),money(r.commission)]))}<h2>Категории</h2>${table(['Категория','Шт.','Продажи'],a.categories.map(r=>[esc(r.name),r.quantity,money(r.revenue)]))}<h2>История выплат · ${a.month}</h2>${table(['Дата','Кто записал','Кому','Сумма','Чек'],a.payments.map(r=>[esc(r.day),esc(r.actorName),esc(r.supplierName),money(r.amount),r.receipt?'Прикреплён':'Нет']))}<h2>Продажи подробно · ${a.month}</h2>${table(['Дата','Заказ','Покупатель','Товар','Поставщик','Шт.','Сумма','Комиссия'],a.sales.map(r=>[esc(r.date),esc(r.order),esc(r.buyer),esc(r.name),esc(r.supplier),r.quantity,money(r.revenue),money(r.commission)]))}`;
}
